package net.civeira.phylax.feature.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BackchannelClientNotificationEndpointVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property backchannel client notification endpoint of oauth client ")
  void test_backchannel_client_notification_endpoint_v_o_builder() {
    Assertions.assertFalse(
        BackchannelClientNotificationEndpointVO.nullValue()
            .getBackchannelClientNotificationEndpoint().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        BackchannelClientNotificationEndpointVO.tryFrom(null)
            .getBackchannelClientNotificationEndpoint().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", BackchannelClientNotificationEndpointVO.from("one")
        .getBackchannelClientNotificationEndpoint().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> BackchannelClientNotificationEndpointVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]",
        BackchannelClientNotificationEndpointVO.from("one").toString());
  }
}
